import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.IOException;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Solver solver = new Solver();
        solver.solve(1, in, out);
        out.close();
    }

    static class Solver {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int a = in.nextInt();
            int b = in.nextInt();
            int left = in.nextInt() - 1;
            int right = in.nextInt() - 1;
            int ab = a + b;
            int[] arr = new int[ab * 4];

            int t = left / ab;
            left -= t * ab;
            right -= t * ab;
            t = (right - left + 1) / ab;
            if (t > 2) {
                right -= (t - 2) * ab;
            }

            int d = a > b ? a - b : 1;

            for (t = 0; t < 4; t++) {
                for (int k = 0; k < a - d; k++) {
                    arr[ab * t + k] = k;
                }
                for (int k = 0; k < d; k++) {
                    arr[ab * t + a - d + k] = t % 2 == 0 ? a - d + k : a + k;
                }
            }

            int ans = a + a;
            for (int k0 = 1; k0 <= d; k0++) {
                for (int k = 0; k < b; k++) {
                    arr[a + k] = arr[a - k0];
                }
                for (int k1 = 1; k1 <= d; k1++) {
                    for (int k = 0; k < b; k++) {
                        arr[ab + a + k] = arr[ab + a - k1];
                    }
                    for (int k2 = 1; k2 <= d; k2++) {
                        for (int k = 0; k < b; k++) {
                            arr[2 * ab + a + k] = arr[2 * ab + a - k2];
                        }
                        for (int k3 = 1; k3 <= d; k3++) {
                            for (int k = 0; k < b; k++) {
                                arr[3 * ab + a + k] = arr[3 * ab + a - k3];
                            }
                            ans = Math.min(ans, count(arr, left, right));
                        }
                    }
                }
            }
            out.println(ans);
        }

        static int count(int[] arr, int l, int r) {
            boolean[] used = new boolean[24];
            int cnt = 0;
            for (int i = l; i <= r; i++) {
                int c = arr[i];
                if (!used[c]) {
                    used[c] = true;
                    cnt++;
                }
            }
            return cnt;
        }
    }

    static class FastScanner {
        private InputStream stream;
        private boolean eof;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (eof) {
                throw new InputMismatchException();
            }
            try {
                int val = stream.read();
                if (val == -1) {
                    eof = true;
                    return -1;
                }
                return val;
            } catch (IOException e) {
                throw new InputMismatchException();
            }
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c == ',') {
                    c = read();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
